-- Robotics/Embedded/IoT pathway ("Vector Division") Act 27 -- "Simulation"
-- content, inside Arc V ("Give Robots a Nervous System," Acts 24-27).
-- World row world-vec-simulation already exists (created by 20260813360000).
-- 1 campaign, 2 operations, 12 missions (11 lessons + boss), following the
-- same campaigns -> operations -> missions -> dialogue -> objectives ->
-- challenges -> hints pattern as every other pathway. No new ChallengeType
-- needed -- reuses story_dialogue, multiple_choice, drag_and_drop,
-- investigation, interactive_diagram and boss_encounter.
--
-- Narrative thread: Act 26 closed on Vector Division deciding to start
-- "breaking things safely, on purpose, before reality does it without
-- warning" -- this Act is exactly that. Dr. Lin Ortega walks the player
-- through building a real simulation environment (robot models, the
-- simulator itself, worlds, simulated sensors, physics parameters, noise
-- models, simulation time, scenario testing, synthetic data and
-- hardware-in-the-loop concepts), and the very first scenario run
-- end-to-end passes cleanly in simulation and fails immediately on the
-- real robot. The boss resolves it: the ground-plane friction coefficient
-- was left at the simulator's unmodified default rather than the real
-- floor's measured value, the simulated lidar's noise model was left at
-- its own unmodified default rather than the real sensor's measured
-- noise, and hardware-in-the-loop testing -- putting one real component
-- back into the loop before trusting simulation blind -- is exactly the
-- validation step that would have caught both gaps before deployment.
-- Closes on the pivot into Act 28, trusting an autonomous decision-making
-- stack enough to let it act without a human confirming every move.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-vec-simulation', 'world-vec-simulation', 'simulation', '5C - Simulation', 'Learn why teams simulate before touching hardware -- robot models, the simulator itself, worlds, sensors in simulation, physics parameters, noise models, simulation time, scenario testing, synthetic data and hardware-in-the-loop concepts -- while Dr. Lin Ortega builds Vector Division''s first real simulation environment, and its very first scenario passes cleanly in simulation and fails immediately on the real robot.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-vec-simulation-1', 'campaign-vec-simulation', 'building-the-sandbox', 'Building the Sandbox', 'Why simulate, robot models, the simulator''s own systems, worlds, sensors in simulation, and physics parameters.', 1),
  ('operation-vec-simulation-2', 'campaign-vec-simulation', 'the-scenario-that-lied', 'The Scenario That Lied', 'Noise models, simulation time, scenario testing, synthetic data, hardware-in-the-loop concepts, and the scenario that passed cleanly and then failed.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-vec-simulation-01', 'world-vec-simulation', 'campaign-vec-simulation', 'operation-vec-simulation-1', 'why-simulate', 'Why Simulate?', 'Vector Division commits to building a real simulation environment instead of continuing to test new behavior directly on hardware -- and Dr. Lin Ortega starts with the question that decides everything else: what is a simulation actually for.', 'beginner', ARRAY['imani','lin'], null, null, '{"type":"simulation","simulationId":"why-simulate-sim"}'::jsonb, '{"xp":340,"credits":25}'::jsonb, false, 1),
  ('mission-vec-simulation-02', 'world-vec-simulation', 'campaign-vec-simulation', 'operation-vec-simulation-1', 'robot-models', 'Robot Models', 'Before a robot can move inside a simulator, the simulator needs to know what that robot actually is -- not a paragraph of description, but an exact model of every link, joint and mass that makes it move the way it does.', 'beginner', ARRAY['lin'], '{"requiredMissionIds":["mission-vec-simulation-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"robot-models-sim"}'::jsonb, '{"xp":340,"credits":30}'::jsonb, false, 2),
  ('mission-vec-simulation-03', 'world-vec-simulation', 'campaign-vec-simulation', 'operation-vec-simulation-1', 'gazebo-concepts', 'Gazebo Concepts', 'The simulator itself is not one program doing everything at once. It is a physics engine, a rendering engine and a plugin system working together, and understanding which does what explains what a simulation can and cannot be trusted to show.', 'beginner', ARRAY['lin','byte'], '{"requiredMissionIds":["mission-vec-simulation-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"gazebo-concepts-sim"}'::jsonb, '{"xp":350,"credits":30}'::jsonb, false, 3),
  ('mission-vec-simulation-04', 'world-vec-simulation', 'campaign-vec-simulation', 'operation-vec-simulation-1', 'simulation-worlds', 'Worlds', 'A robot model describes the robot. It says nothing about the floor it stands on, the shelving around it, or the lighting overhead -- that is an entirely separate file, and its accuracy matters exactly as much as the robot model''s does.', 'beginner', ARRAY['lin'], '{"requiredMissionIds":["mission-vec-simulation-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"simulation-worlds-sim"}'::jsonb, '{"xp":350,"credits":35}'::jsonb, false, 4),
  ('mission-vec-simulation-05', 'world-vec-simulation', 'campaign-vec-simulation', 'operation-vec-simulation-1', 'sensors-in-simulation', 'Sensors in Simulation', 'A simulated sensor never touches the real world. It reads the simulator''s own internal state and manufactures a plausible camera image, lidar scan or IMU reading from it -- close enough that the robot''s perception code cannot tell the difference, in theory.', 'beginner', ARRAY['lin','byte'], '{"requiredMissionIds":["mission-vec-simulation-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"sensors-in-simulation-sim"}'::jsonb, '{"xp":360,"credits":35}'::jsonb, false, 5),
  ('mission-vec-simulation-06', 'world-vec-simulation', 'campaign-vec-simulation', 'operation-vec-simulation-1', 'physics-parameters', 'Physics Parameters', 'Every simulated collision, every bit of traction a simulated wheel gets, is governed by a handful of numbers called physics parameters -- and like any number nobody has checked, a default value can sit unquestioned for a long time before it matters.', 'beginner', ARRAY['lin'], '{"requiredMissionIds":["mission-vec-simulation-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"physics-parameters-sim"}'::jsonb, '{"xp":360,"credits":35}'::jsonb, false, 6),
  ('mission-vec-simulation-07', 'world-vec-simulation', 'campaign-vec-simulation', 'operation-vec-simulation-2', 'noise-models', 'Noise Models', 'A real sensor never reports a clean, perfect measurement twice in a row. A simulated sensor without a noise model does -- and that single difference can make an algorithm look flawless in simulation for reasons that have nothing to do with how good it actually is.', 'beginner', ARRAY['lin','byte'], '{"requiredMissionIds":["mission-vec-simulation-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"noise-models-sim"}'::jsonb, '{"xp":370,"credits":40}'::jsonb, false, 7),
  ('mission-vec-simulation-08', 'world-vec-simulation', 'campaign-vec-simulation', 'operation-vec-simulation-2', 'simulation-time', 'Simulation Time', 'The clock a simulation runs on is not the clock on the wall. Simulation time can run faster, slower or in careful lockstep with real time, and a controller tuned against the wrong one will behave differently the moment it meets real hardware.', 'beginner', ARRAY['lin'], '{"requiredMissionIds":["mission-vec-simulation-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"simulation-time-sim"}'::jsonb, '{"xp":370,"credits":40}'::jsonb, false, 8),
  ('mission-vec-simulation-09', 'world-vec-simulation', 'campaign-vec-simulation', 'operation-vec-simulation-2', 'scenario-testing', 'Scenario Testing', 'A scenario is not just "run the robot." It is a specific, repeatable set of starting conditions and events, built so the exact same test can be run a hundred times and a hundred times more after every change -- the foundation of testing anything safely before hardware ever sees it.', 'beginner', ARRAY['lin','imani'], '{"requiredMissionIds":["mission-vec-simulation-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"scenario-testing-sim"}'::jsonb, '{"xp":380,"credits":40}'::jsonb, false, 9),
  ('mission-vec-simulation-10', 'world-vec-simulation', 'campaign-vec-simulation', 'operation-vec-simulation-2', 'synthetic-data', 'Synthetic Data', 'A simulator does not just test behavior. Run enough varied scenarios through it and it becomes a factory for labeled training data -- as long as nobody lets a perception model learn to recognize one simulated scene instead of the real world it is meant for.', 'beginner', ARRAY['lin','byte'], '{"requiredMissionIds":["mission-vec-simulation-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"synthetic-data-sim"}'::jsonb, '{"xp":380,"credits":45}'::jsonb, false, 10),
  ('mission-vec-simulation-11', 'world-vec-simulation', 'campaign-vec-simulation', 'operation-vec-simulation-2', 'hardware-in-the-loop', 'Hardware-in-the-Loop Concepts', 'A simulation that only ever talks to itself can drift from reality for a long time before anyone notices. Hardware-in-the-loop testing closes part of that gap deliberately, by putting one real component back into the loop before anything is trusted blind.', 'beginner', ARRAY['lin','byte'], '{"requiredMissionIds":["mission-vec-simulation-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"hardware-in-the-loop-sim"}'::jsonb, '{"xp":390,"credits":45}'::jsonb, false, 11),
  ('mission-vec-simulation-12', 'world-vec-simulation', 'campaign-vec-simulation', 'operation-vec-simulation-2', 'simulation-lied', 'Simulation Lied', 'The first scenario Vector Division ever ran end-to-end in simulation passed cleanly, exactly as designed. On the real robot, on the real floor, it failed within seconds -- and tonight''s job is to find out exactly which part of the simulation lied, and why nobody caught it first.', 'boss', ARRAY['imani','lin','byte'], '{"requiredMissionIds":["mission-vec-simulation-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"simulation-lied-boss-sim"}'::jsonb, '{"xp":2000,"credits":410,"badgeIds":["simulation-lied"],"skillXp":{"robotics_fundamentals":290}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-vec-simulation-01', 1, 'imani', 'Last time, we decided reality was not something we could keep testing on by accident. Starting tonight, Vector Division builds a real simulation environment -- somewhere to break things safely, on purpose, before the real floor does it for us.'),
  ('mission-vec-simulation-01', 2, 'lin', 'Good. Then the first question is not "how do we build one." It is "what is a simulation actually for." A simulation is a model of a robot and a model of the world it operates in, run together so we can test behavior without ever touching real hardware.'),
  ('mission-vec-simulation-01', 3, 'lin', 'That buys us three things a real robot cannot. We can run the same dangerous scenario a thousand times without wearing out a single motor. We can run many scenarios in parallel instead of one at a time. And we can rewind and inspect exactly what happened, which a real collision never lets us do.'),
  ('mission-vec-simulation-01', 4, 'imani', 'Just remember what a simulation actually is while you build it. It is a claim about how the world behaves. It is not the world. Every claim in it has to be checked, or it is worth exactly nothing.'),

  ('mission-vec-simulation-02', 1, 'lin', 'A simulator cannot move a robot it does not understand. Before anything else, it needs a robot model -- links for every rigid piece of the body, joints for how those pieces connect and move relative to each other, and a mass and inertia value for each link so physics can act on it correctly.'),
  ('mission-vec-simulation-02', 2, 'lin', 'Two more properties, every link. A visual geometry, the detailed shape rendered on screen. And a collision geometry, a simplified shape the physics engine actually checks for contact. They are almost never the same shape.'),
  ('mission-vec-simulation-02', 3, 'byte', 'We already built exactly this description for the arm, back when kinematics mattered. Same file format, new job -- it just never had to describe a whole robot to a physics engine before.'),

  ('mission-vec-simulation-03', 1, 'lin', 'The simulator itself is three systems wearing one interface. A physics engine that steps forward in small time increments, computing forces, collisions and motion. A rendering engine that draws what a camera would see. And a plugin system that attaches behavior -- sensors, controllers, custom logic -- onto a model or the world itself.'),
  ('mission-vec-simulation-03', 2, 'byte', 'Plugins are also how the simulator talks to ROS 2 at all. Without a plugin bridging a simulated sensor''s output onto a real topic, the rest of our stack has no idea the simulator exists.'),
  ('mission-vec-simulation-03', 3, 'lin', 'Which means the physics engine can be perfectly correct and the whole simulation can still lie to us, if the wrong plugin is doing the reporting.'),

  ('mission-vec-simulation-04', 1, 'lin', 'A robot model only describes the robot. Everything around it -- the ground plane, walls, shelving, obstacles, lighting -- lives in a separate file entirely: the world.'),
  ('mission-vec-simulation-04', 2, 'lin', 'A world file is a claim about a place, the same way a robot model is a claim about a machine. Load the wrong world, or an inaccurate one, and a robot can behave perfectly and still be tested against a floor that does not exist anywhere in our facility.'),
  ('mission-vec-simulation-04', 3, 'byte', 'Right now our starter world is a flat, empty plane with one generic obstacle block. It was never built to match any specific aisle in the warehouse. Worth remembering, going forward.'),

  ('mission-vec-simulation-05', 1, 'lin', 'A simulated sensor never touches anything real. A simulated camera plugin renders the scene from a virtual lens position. A simulated lidar plugin casts virtual rays through the physics engine''s geometry and reports where they stop. Neither one measures the physical world, because there is no physical world here to measure.'),
  ('mission-vec-simulation-05', 2, 'lin', 'Done well, the output still looks exactly like a real sensor''s message on a real topic, so the perception code downstream runs completely unmodified, unaware it is reading synthetic data at all.'),
  ('mission-vec-simulation-05', 3, 'byte', 'Unmodified does not mean identical. A simulated sensor is only as honest as whatever assumptions went into building it.'),

  ('mission-vec-simulation-06', 1, 'lin', 'Underneath every simulated collision and every bit of traction a simulated wheel gets are physics parameters -- plain numbers. Friction coefficient, how much two surfaces resist sliding against each other. Restitution, how much energy a collision keeps versus loses. Damping. Gravity, usually left alone.'),
  ('mission-vec-simulation-06', 2, 'lin', 'None of these numbers are guessed by the physics engine. Every one of them is set by whoever builds the simulation -- and every one of them ships with a default value that was never meant to describe any specific real floor.'),
  ('mission-vec-simulation-06', 3, 'byte', 'I checked our world file. The ground-plane friction coefficient is still whatever the starter template shipped with. Nobody has touched it since we imported it.'),

  ('mission-vec-simulation-07', 1, 'lin', 'A real sensor never reports a clean number twice. Point a real lidar at a perfectly still wall and read it a hundred times, and the range comes back slightly different almost every time -- electrical noise, tiny vibration, the sensor''s own imperfections.'),
  ('mission-vec-simulation-07', 2, 'lin', 'A simulated sensor with no noise model does not do that. It reports the mathematically exact distance, every single time, which makes any algorithm tested against it look far more stable than it will ever be for real. A noise model deliberately adds artificial variation, usually random values drawn from a Gaussian distribution, to close that gap.'),
  ('mission-vec-simulation-07', 3, 'byte', 'Our lidar plugin does have a noise model. I have never actually checked whether its numbers came from this sensor''s real datasheet, or just from whatever the plugin shipped with by default.'),

  ('mission-vec-simulation-08', 1, 'lin', 'A simulation does not have to run on the same clock as the room around it. Simulation time is the clock the physics engine advances internally -- it can run faster than real time, slower than real time, or locked exactly to it, one to one.'),
  ('mission-vec-simulation-08', 2, 'lin', 'The real-time factor is the ratio between them. A factor of two means the simulation is living two seconds of physics for every one second that actually passes for us. Every node that cares about timing has to agree on which clock it is reading.'),
  ('mission-vec-simulation-08', 3, 'byte', 'Which is exactly why every one of our nodes needs the use_sim_time parameter set correctly when we test in simulation. A controller tuned and tested only ever against a real-time factor of one can behave differently the moment it meets a real clock it was never checked against.'),

  ('mission-vec-simulation-09', 1, 'lin', 'A scenario is not "turn the robot on and see what happens." It is a specific, written-down set of starting conditions -- robot position, obstacle placement, sensor state -- plus a specific sequence of events, built so the exact same test can be re-run identically, tomorrow and after every code change.'),
  ('mission-vec-simulation-09', 2, 'byte', 'That repeatability is the entire point. Without it, "it worked in testing" means nothing, because nobody could ever prove the test that passed was the same test being run again.'),

  ('mission-vec-simulation-10', 1, 'lin', 'A simulator is not just a test bench. Run enough scenarios through it and every one produces labeled data for free -- an image, and the exact, perfectly known ground truth of what is actually in it, with no human labeler required.'),
  ('mission-vec-simulation-10', 2, 'lin', 'The danger is a model that learns our one simulated aisle instead of aisles in general. Domain randomization is the fix: vary lighting, textures, obstacle placement and noise across many simulated runs on purpose, so a model trained on it generalizes instead of memorizing one scene.'),
  ('mission-vec-simulation-10', 3, 'byte', 'Which means synthetic data is only as useful as how much it was deliberately varied. A thousand identical simulated images teach a model almost nothing a single one did not already.'),

  ('mission-vec-simulation-11', 1, 'lin', 'A simulation that only ever talks to itself -- simulated controller commanding a simulated actuator, reading a simulated sensor -- can drift from reality for a long time before anyone notices, because nothing in that loop is ever forced to answer to anything real.'),
  ('mission-vec-simulation-11', 2, 'lin', 'Hardware-in-the-loop testing breaks that isolation on purpose. One real component -- real controller firmware, or a real sensor, or a real actuator -- gets wired directly into an otherwise simulated loop, so its actual behavior has to agree with everything simulated around it.'),
  ('mission-vec-simulation-11', 3, 'byte', 'It will not catch every gap. But it is the one validation step specifically built to catch the difference between what a component is assumed to do in software and what it actually does -- before that gap ever reaches a full deployment.'),

  ('mission-vec-simulation-12', 1, 'imani', 'The first scenario we ever ran end-to-end passed cleanly in simulation -- the robot navigated the aisle, held its planned path, avoided the obstacle exactly as designed. On the real floor, in the real aisle, it skidded into the exact obstacle it was supposed to avoid, within seconds.'),
  ('mission-vec-simulation-12', 2, 'lin', 'Nothing in the simulation was malicious, and nothing in it was technically wrong. It ran exactly the numbers it was given. Which means our job tonight is finding out which number was wrong, not looking for a bug that does not exist.'),
  ('mission-vec-simulation-12', 3, 'byte', 'I pulled the world file and the sensor config used for that scenario. Two things stand out immediately, and neither one is a coincidence.'),
  ('mission-vec-simulation-12', 4, 'lin', 'Walk me through the physics first. Then the sensors. Then tell me what would have caught both before tonight ever happened.'),
  ('mission-vec-simulation-12', 5, 'byte', 'On it.'),
  ('mission-vec-simulation-12', 6, 'imani', 'Whatever it is, it clears simulation of being useless. It does not clear us of trusting an unvalidated one.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-vec-simulation-01-o1', 'mission-vec-simulation-01', 1, 'State simulation''s purpose', 'Choose the accurate description of what running a simulation actually buys a team before hardware is involved.'),
  ('mission-vec-simulation-01-o2', 'mission-vec-simulation-01', 2, 'Judge simulation''s limit', 'State what a simulation is, and is not, entitled to claim about the real world.'),

  ('mission-vec-simulation-02-o1', 'mission-vec-simulation-02', 1, 'Name the model''s parts', 'Identify which properties a robot model must define for a physics engine to move it correctly.'),
  ('mission-vec-simulation-02-o2', 'mission-vec-simulation-02', 2, 'Explain the two geometries', 'Judge why a link''s visual geometry and its collision geometry are usually not the same shape.'),

  ('mission-vec-simulation-03-o1', 'mission-vec-simulation-03', 1, 'Separate the simulator''s systems', 'Sort each responsibility into the physics engine, the rendering engine, or the plugin system.'),
  ('mission-vec-simulation-03-o2', 'mission-vec-simulation-03', 2, 'Explain the plugin bridge', 'State why a simulated sensor is invisible to the rest of the ROS 2 stack without a plugin.'),

  ('mission-vec-simulation-04-o1', 'mission-vec-simulation-04', 1, 'Define a world file', 'Choose the accurate description of what a world file specifies, as distinct from a robot model.'),
  ('mission-vec-simulation-04-o2', 'mission-vec-simulation-04', 2, 'Judge the world''s accuracy', 'Find the evidence showing our current world file does not represent any real facility location.'),

  ('mission-vec-simulation-05-o1', 'mission-vec-simulation-05', 1, 'Explain what a simulated sensor produces', 'Choose the accurate description of how a simulated sensor plugin generates its output.'),
  ('mission-vec-simulation-05-o2', 'mission-vec-simulation-05', 2, 'Explain interface compatibility', 'State why perception code written for a real sensor can run unmodified against a simulated one.'),

  ('mission-vec-simulation-06-o1', 'mission-vec-simulation-06', 1, 'Define a friction coefficient', 'Choose the accurate description of what a friction coefficient actually represents physically.'),
  ('mission-vec-simulation-06-o2', 'mission-vec-simulation-06', 2, 'Judge the risk of an unvalidated default', 'Find the evidence showing our simulation''s physics parameters were never validated against anything real.'),

  ('mission-vec-simulation-07-o1', 'mission-vec-simulation-07', 1, 'Explain why real sensors vary', 'Choose the accurate description of why a real sensor reports a slightly different value on repeated readings of the same static thing.'),
  ('mission-vec-simulation-07-o2', 'mission-vec-simulation-07', 2, 'Judge the risk of an unvalidated noise model', 'Find the evidence showing our simulated sensor''s noise model was never checked against this sensor''s real behavior.'),

  ('mission-vec-simulation-08-o1', 'mission-vec-simulation-08', 1, 'Define simulation time', 'Choose the accurate description of simulation time and the real-time factor.'),
  ('mission-vec-simulation-08-o2', 'mission-vec-simulation-08', 2, 'Judge the timing risk', 'State what can go wrong for a controller tuned only against one real-time factor.'),

  ('mission-vec-simulation-09-o1', 'mission-vec-simulation-09', 1, 'Define a scenario', 'Choose the accurate description of what makes a test a scenario rather than an unstructured run.'),
  ('mission-vec-simulation-09-o2', 'mission-vec-simulation-09', 2, 'Explain why repeatability matters', 'State what repeatability actually proves that a single successful run cannot.'),

  ('mission-vec-simulation-10-o1', 'mission-vec-simulation-10', 1, 'Explain synthetic data''s advantage', 'Choose the accurate description of why simulation can generate labeled training data cheaply.'),
  ('mission-vec-simulation-10-o2', 'mission-vec-simulation-10', 2, 'Judge domain randomization''s role', 'State what domain randomization is protecting a model against.'),

  ('mission-vec-simulation-11-o1', 'mission-vec-simulation-11', 1, 'Define hardware-in-the-loop testing', 'Choose the accurate description of what hardware-in-the-loop testing actually does.'),
  ('mission-vec-simulation-11-o2', 'mission-vec-simulation-11', 2, 'Judge what HIL specifically catches', 'State the kind of gap hardware-in-the-loop testing is built to catch that a pure software simulation cannot.'),

  ('mission-vec-simulation-12-o1', 'mission-vec-simulation-12', 1, 'Diagnose the physics gap', 'Identify which specific physics parameter was left at an unrealistic default and prove it did not match the real floor.'),
  ('mission-vec-simulation-12-o2', 'mission-vec-simulation-12', 2, 'Prove the noise-model gap', 'Prove the simulated sensor''s noise model did not match the real sensor''s actual noise profile either.'),
  ('mission-vec-simulation-12-o3', 'mission-vec-simulation-12', 3, 'Confirm the missed validation', 'State what validation process would have caught this gap before deployment.'),
  ('mission-vec-simulation-12-o4', 'mission-vec-simulation-12', 4, 'State the diagnosis', 'Having judged all three, state exactly why the simulation lied.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-vec-simulation-01-o1-c1', 'mission-vec-simulation-01-o1', 1, 'multiple_choice', 'What does running a scenario in simulation actually buy a team, compared to testing the same scenario directly on hardware first?', '{"question":"What does running a scenario in simulation actually buy a team, compared to testing the same scenario directly on hardware first?","options":[{"id":"a","text":"Nothing meaningfully different, simulation and hardware testing carry identical risk"},{"id":"b","text":"The ability to run the same scenario repeatedly and in parallel, and inspect exactly what happened, without any risk to real hardware or people"},{"id":"c","text":"Simulation always predicts real-world behavior with total accuracy, so hardware testing becomes unnecessary"},{"id":"d","text":"Simulation is only useful for training data, never for testing behavior"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-simulation-01-o2-c1', 'mission-vec-simulation-01-o2', 1, 'multiple_choice', 'What is a simulation, honestly, entitled to claim about the real world?', '{"question":"What is a simulation, honestly, entitled to claim about the real world?","options":[{"id":"a","text":"Whatever passes in simulation is guaranteed to work identically on real hardware"},{"id":"b","text":"A simulation is only ever a model of the world, and every claim it makes is only as trustworthy as how well that model was validated against reality"},{"id":"c","text":"Simulation results require no further validation once the code compiles without errors"},{"id":"d","text":"A simulation cannot be trusted for anything at all, ever"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-simulation-02-o1-c1', 'mission-vec-simulation-02-o1', 1, 'multiple_choice', 'A robot model must define enough for a physics engine to compute motion correctly. Which set of properties is that?', '{"question":"A robot model must define enough for a physics engine to compute motion correctly. Which set of properties is that?","options":[{"id":"a","text":"Only the visual appearance of each part"},{"id":"b","text":"For every link: its mass and inertia, plus how it connects to neighboring links via joints, plus a collision geometry the physics engine can check for contact"},{"id":"c","text":"Only the robot''s top speed and battery capacity"},{"id":"d","text":"Only the names of each part -- physics fills in the rest automatically"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-simulation-02-o2-c1', 'mission-vec-simulation-02-o2', 1, 'multiple_choice', 'Why does a link typically have both a visual geometry and a separate, simpler collision geometry?', '{"question":"Why does a link typically have both a visual geometry and a separate, simpler collision geometry?","options":[{"id":"a","text":"They serve different jobs -- visual geometry is the detailed shape rendered for a human to see, collision geometry is a simplified shape the physics engine checks cheaply, many times per second"},{"id":"b","text":"Collision geometry is only used for camera rendering"},{"id":"c","text":"They are always identical, keeping two versions is only for backup purposes"},{"id":"d","text":"Visual geometry is used by the physics engine and collision geometry is purely cosmetic"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),

  ('mission-vec-simulation-03-o1-c1', 'mission-vec-simulation-03-o1', 1, 'drag_and_drop', 'Sort each responsibility into the system of the simulator that actually performs it.', '{"items":[{"id":"i1","text":"Computing forces, collisions and motion each time step"},{"id":"i2","text":"Drawing what a camera would see from a given viewpoint"},{"id":"i3","text":"Attaching a sensor''s synthetic output onto a ROS 2 topic"},{"id":"i4","text":"Resolving whether two collision geometries are touching"}],"targets":[{"id":"physics","label":"Physics engine"},{"id":"rendering","label":"Rendering engine"},{"id":"plugin","label":"Plugin system"}]}'::jsonb, '{"correctMapping":{"i1":"physics","i2":"rendering","i3":"plugin","i4":"physics"}}'::jsonb),
  ('mission-vec-simulation-03-o2-c1', 'mission-vec-simulation-03-o2', 1, 'multiple_choice', 'Without a plugin bridging a simulated sensor''s output onto a ROS 2 topic, what happens to the rest of the stack?', '{"question":"Without a plugin bridging a simulated sensor''s output onto a ROS 2 topic, what happens to the rest of the stack?","options":[{"id":"a","text":"Nothing changes, the physics engine reports directly to ROS 2 automatically"},{"id":"b","text":"The rest of the stack has no way to know the simulated sensor, or the simulator itself, exists at all"},{"id":"c","text":"The rendering engine substitutes automatically"},{"id":"d","text":"ROS 2 detects the simulator over the network without any plugin"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-simulation-04-o1-c1', 'mission-vec-simulation-04-o1', 1, 'multiple_choice', 'What does a world file specify, that a robot model does not?', '{"question":"What does a world file specify, that a robot model does not?","options":[{"id":"a","text":"The robot''s joint limits"},{"id":"b","text":"The static environment the robot operates in -- ground plane, obstacles, lighting, and anything not part of the robot itself"},{"id":"c","text":"The robot''s sensor noise parameters"},{"id":"d","text":"The robot''s exact firmware version"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-simulation-04-o2-c1', 'mission-vec-simulation-04-o2', 1, 'investigation', 'Which evidence shows the current world file does not represent any real facility location?', '{"evidence":[{"id":"e1","label":"Facilities floor plan","detail":"Real warehouse aisle: uneven epoxy floor, shelving on both sides, seasonal dust buildup near the loading dock"},{"id":"e2","label":"Simulation world file","detail":"Current starter world: a flat, featureless plane and one generic block obstacle, imported unmodified from the simulator''s example template"},{"id":"e3","label":"Robot maintenance log","detail":"Wheel bearings inspected and replaced on schedule last month"}],"question":"Which evidence shows the current world file does not represent any real facility location?"}'::jsonb, '{"requiredEvidenceIds":["e1","e2"]}'::jsonb),

  ('mission-vec-simulation-05-o1-c1', 'mission-vec-simulation-05-o1', 1, 'multiple_choice', 'How does a simulated lidar plugin actually produce a range reading?', '{"question":"How does a simulated lidar plugin actually produce a range reading?","options":[{"id":"a","text":"It reads a real lidar sensor connected to the development machine"},{"id":"b","text":"It casts virtual rays through the physics engine''s known geometry and reports where each ray stops, entirely computed, with nothing physically measured"},{"id":"c","text":"It replays a pre-recorded real lidar log regardless of the robot''s simulated position"},{"id":"d","text":"It asks the rendering engine for a photograph and converts pixel colors into distances"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-simulation-05-o2-c1', 'mission-vec-simulation-05-o2', 1, 'multiple_choice', 'Why can perception code written for a real sensor usually run unmodified against a simulated one?', '{"question":"Why can perception code written for a real sensor usually run unmodified against a simulated one?","options":[{"id":"a","text":"Simulated sensors always produce identical data to the real sensor, so no adaptation is ever needed"},{"id":"b","text":"A well-built sensor plugin publishes its synthetic output using the same message type and topic interface a real sensor would, so downstream code cannot tell the difference structurally"},{"id":"c","text":"Perception code is rewritten separately for simulation every time"},{"id":"d","text":"Simulated sensors bypass ROS 2 entirely, so no interface compatibility is needed"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-simulation-06-o1-c1', 'mission-vec-simulation-06-o1', 1, 'multiple_choice', 'A friction coefficient in a physics engine represents...', '{"question":"A friction coefficient in a physics engine represents...","options":[{"id":"a","text":"How much two surfaces resist sliding against each other, higher values meaning more resistance to slipping"},{"id":"b","text":"The exact top speed a wheel can reach"},{"id":"c","text":"How much energy is lost per second regardless of contact"},{"id":"d","text":"The color of the two surfaces in contact"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-vec-simulation-06-o2-c1', 'mission-vec-simulation-06-o2', 1, 'investigation', 'Which evidence shows the simulation''s physics parameters were never validated against anything real?', '{"evidence":[{"id":"e1","label":"World file audit","detail":"The ground-plane friction coefficient was never changed from the value shipped with the simulator''s starter template"},{"id":"e2","label":"Facilities floor survey","detail":"No formal measurement of the real warehouse floor''s friction has ever been compared against the simulation''s value"},{"id":"e3","label":"Robot firmware log","detail":"Motor controller firmware last updated two releases ago"}],"question":"Which evidence shows the simulation''s physics parameters were never validated against anything real?"}'::jsonb, '{"requiredEvidenceIds":["e1","e2"]}'::jsonb),

  ('mission-vec-simulation-07-o1-c1', 'mission-vec-simulation-07-o1', 1, 'multiple_choice', 'Why does a real sensor report a slightly different value each time it measures the same static object?', '{"question":"Why does a real sensor report a slightly different value each time it measures the same static object?","options":[{"id":"a","text":"It does not, real sensors are always perfectly consistent"},{"id":"b","text":"Electrical noise, tiny vibration and the sensor''s own physical imperfections introduce small random variation into every real reading"},{"id":"c","text":"The object itself is actually moving without anyone noticing"},{"id":"d","text":"Sensors round every reading to the nearest whole number, creating apparent variation"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-simulation-07-o2-c1', 'mission-vec-simulation-07-o2', 1, 'investigation', 'Which evidence shows the simulated sensor''s noise model was never checked against this sensor''s real behavior?', '{"evidence":[{"id":"e1","label":"Sensor plugin config","detail":"Simulated lidar noise model: Gaussian noise with a standard deviation of 0.01 meters, the plugin''s built-in default value"},{"id":"e2","label":"Field measurement report","detail":"The real lidar mounted on the robot measures a standard deviation closer to 0.05 meters in practice, with added dropout noise near reflective shelving"},{"id":"e3","label":"Camera firmware note","detail":"Camera firmware unchanged since installation"}],"question":"Which evidence shows the simulated sensor''s noise model was never checked against this sensor''s real behavior?"}'::jsonb, '{"requiredEvidenceIds":["e1","e2"]}'::jsonb),

  ('mission-vec-simulation-08-o1-c1', 'mission-vec-simulation-08-o1', 1, 'multiple_choice', 'The real-time factor of a simulation describes...', '{"question":"The real-time factor of a simulation describes...","options":[{"id":"a","text":"How many robots the simulation can run at once"},{"id":"b","text":"The ratio between simulated time and real wall-clock time -- a factor of two means twice as much simulated time passes per second of real time"},{"id":"c","text":"How many CPU cores the simulator is using"},{"id":"d","text":"The frame rate of the rendering engine only"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-simulation-08-o2-c1', 'mission-vec-simulation-08-o2', 1, 'multiple_choice', 'A controller was tuned and tested only ever at a real-time factor of one. What is the risk of trusting it unchanged at a different real-time factor?', '{"question":"A controller was tuned and tested only ever at a real-time factor of one. What is the risk of trusting it unchanged at a different real-time factor?","options":[{"id":"a","text":"None, controllers are always independent of simulation timing"},{"id":"b","text":"Its timing-dependent behavior -- how it reacts within a control loop period -- can differ from what was tested, since it was never validated against that relationship between simulated and real time"},{"id":"c","text":"The robot''s appearance changes, nothing about its behavior does"},{"id":"d","text":"Real-time factor only affects rendering, never control logic"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-simulation-09-o1-c1', 'mission-vec-simulation-09-o1', 1, 'multiple_choice', 'What actually makes a test a scenario, rather than just "turning the robot on and seeing what happens"?', '{"question":"What actually makes a test a scenario, rather than just \"turning the robot on and seeing what happens\"?","options":[{"id":"a","text":"A scenario has no starting conditions at all, only an ending"},{"id":"b","text":"A scenario is a specific, written-down set of starting conditions and a specific sequence of events, deliberately built to be run identically again"},{"id":"c","text":"A scenario always requires real hardware to be valid"},{"id":"d","text":"A scenario is only defined by how long the test runs"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-simulation-09-o2-c1', 'mission-vec-simulation-09-o2', 1, 'multiple_choice', 'What does repeatability actually prove that a single successful run cannot?', '{"question":"What does repeatability actually prove that a single successful run cannot?","options":[{"id":"a","text":"Nothing extra, one successful run is already sufficient proof"},{"id":"b","text":"That the same behavior holds reliably, not just once by chance -- and that the exact same test can be re-run identically after every future change, to check nothing broke"},{"id":"c","text":"That the robot''s hardware will never fail"},{"id":"d","text":"That the simulation is running faster than real time"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-simulation-10-o1-c1', 'mission-vec-simulation-10-o1', 1, 'multiple_choice', 'Why can a simulator generate labeled training data cheaply, compared to collecting it from the real world?', '{"question":"Why can a simulator generate labeled training data cheaply, compared to collecting it from the real world?","options":[{"id":"a","text":"It cannot, synthetic data is always lower quality than real data"},{"id":"b","text":"The simulator already knows the exact ground truth of everything in the scene, so every generated image comes with a perfect label automatically, with no human annotation required"},{"id":"c","text":"Synthetic data does not require any images at all"},{"id":"d","text":"Labeled data can only ever come from real sensors"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-simulation-10-o2-c1', 'mission-vec-simulation-10-o2', 1, 'multiple_choice', 'What is domain randomization specifically protecting a perception model against?', '{"question":"What is domain randomization specifically protecting a perception model against?","options":[{"id":"a","text":"Running out of storage space for training data"},{"id":"b","text":"Learning to recognize one specific simulated scene instead of generalizing to the variety the real world actually contains"},{"id":"c","text":"Simulation running too fast to collect data"},{"id":"d","text":"The robot''s physical wear over time"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-simulation-11-o1-c1', 'mission-vec-simulation-11-o1', 1, 'multiple_choice', 'Hardware-in-the-loop testing is best described as...', '{"question":"Hardware-in-the-loop testing is best described as...","options":[{"id":"a","text":"Running the entire system purely in software, with nothing real involved at all"},{"id":"b","text":"Wiring one real component -- controller firmware, a sensor, or an actuator -- directly into an otherwise simulated loop, so its actual behavior has to agree with everything simulated around it"},{"id":"c","text":"Testing hardware exclusively on the factory floor with no simulation involved"},{"id":"d","text":"A synonym for running a simulation faster than real time"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-simulation-11-o2-c1', 'mission-vec-simulation-11-o2', 1, 'multiple_choice', 'What kind of gap is hardware-in-the-loop testing specifically built to catch, that a purely software simulation cannot?', '{"question":"What kind of gap is hardware-in-the-loop testing specifically built to catch, that a purely software simulation cannot?","options":[{"id":"a","text":"Syntax errors in the simulation code"},{"id":"b","text":"The actual difference between how a real component behaves and how it was merely assumed to behave in software, before that assumption ever reaches full deployment"},{"id":"c","text":"Errors in the rendering engine''s graphics only"},{"id":"d","text":"Nothing meaningfully different from pure software simulation"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-simulation-12-o1-c1', 'mission-vec-simulation-12-o1', 1, 'investigation', 'Which two pieces of evidence together prove the friction coefficient was left at an unrealistic default that did not match the real floor?', '{"evidence":[{"id":"e1","label":"World file audit","detail":"Ground-plane friction coefficient in the failed scenario''s world file: 1.0, the physics engine''s unmodified default, imported from the starter template and never revisited"},{"id":"e2","label":"Facilities floor survey","detail":"Measured friction coefficient of the real aisle floor, including its usual light dust layer: approximately 0.35, roughly a third of the simulated value"},{"id":"e3","label":"Robot maintenance log","detail":"Wheel bearings inspected and replaced on schedule last month"}],"question":"Which two pieces of evidence together prove the friction coefficient was left at an unrealistic default that did not match the real floor?"}'::jsonb, '{"requiredEvidenceIds":["e1","e2"]}'::jsonb),
  ('mission-vec-simulation-12-o2-c1', 'mission-vec-simulation-12-o2', 1, 'investigation', 'Which two pieces of evidence together prove the simulated sensor''s noise model did not match the real sensor''s actual noise profile?', '{"evidence":[{"id":"e1","label":"Sensor plugin config","detail":"Simulated lidar noise model used in the scenario: Gaussian noise, standard deviation 0.01 meters, the plugin''s built-in default, never checked against this sensor''s datasheet or field behavior"},{"id":"e2","label":"Field measurement report","detail":"The real lidar''s actual measured standard deviation is close to 0.05 meters, with additional dropout noise near reflective shelving that the simulated model does not represent at all"},{"id":"e3","label":"Camera firmware note","detail":"Camera firmware unchanged since installation, unrelated to the lidar finding"}],"question":"Which two pieces of evidence together prove the simulated sensor''s noise model did not match the real sensor''s actual noise profile?"}'::jsonb, '{"requiredEvidenceIds":["e1","e2"]}'::jsonb),
  ('mission-vec-simulation-12-o3-c1', 'mission-vec-simulation-12-o3', 1, 'multiple_choice', 'Given both the friction mismatch and the noise-model mismatch, what validation step would have caught this gap before the robot ever ran the scenario on the real floor?', '{"question":"Given both the friction mismatch and the noise-model mismatch, what validation step would have caught this gap before the robot ever ran the scenario on the real floor?","options":[{"id":"a","text":"Running the scenario in simulation one additional time, with the same unvalidated parameters"},{"id":"b","text":"Hardware-in-the-loop testing that puts the real lidar''s actual output, and ideally the robot''s real wheels on the real floor surface, into the loop before trusting the pure software simulation blindly"},{"id":"c","text":"Rendering the simulation at a higher visual resolution"},{"id":"d","text":"Increasing the simulation''s real-time factor so the scenario finishes faster"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-simulation-12-o4-c1', 'mission-vec-simulation-12-o4', 1, 'boss_encounter', 'Having diagnosed the physics gap, proven the noise-model gap, and confirmed the missed validation, state exactly why the simulation lied.', '{"stages":[{"objectiveRef":"mission-vec-simulation-12-o1","label":"Diagnose the physics gap"},{"objectiveRef":"mission-vec-simulation-12-o2","label":"Prove the noise-model gap"},{"objectiveRef":"mission-vec-simulation-12-o3","label":"Confirm the missed validation"}],"task":"State the diagnosis in one sentence: the ground-plane friction coefficient was left at the physics engine''s unmodified default of 1.0 instead of the real floor''s measured 0.35, the simulated lidar''s noise model was left at its own unmodified default of 0.01 meters instead of the real sensor''s measured 0.05 meters, and hardware-in-the-loop testing -- putting real sensor output and real wheel traction back into the loop -- is exactly the validation step that would have caught both gaps before the scenario ever reached the real floor."}'::jsonb, '{"requiredObjectiveIds":["mission-vec-simulation-12-o1","mission-vec-simulation-12-o2","mission-vec-simulation-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-vec-simulation-01-o1-c1', 'orientation', 'Think about what a real robot cannot survive doing a thousand times in a row.', 10, 1),
  ('mission-vec-simulation-01-o1-c1', 'solution', 'Simulation buys repeated, parallel, inspectable testing with zero risk to real hardware or people.', 20, 2),
  ('mission-vec-simulation-01-o2-c1', 'orientation', 'A model is always a claim about something, never the thing itself.', 10, 1),
  ('mission-vec-simulation-01-o2-c1', 'solution', 'A simulation is only as trustworthy as how well its model was validated against the real world -- passing it proves nothing on its own.', 20, 2),

  ('mission-vec-simulation-02-o1-c1', 'orientation', 'A physics engine cannot compute motion for a part it knows nothing about physically.', 10, 1),
  ('mission-vec-simulation-02-o1-c1', 'solution', 'Every link needs mass, inertia, joints connecting it to its neighbors, and a collision geometry the physics engine can check.', 20, 2),
  ('mission-vec-simulation-02-o2-c1', 'orientation', 'One geometry is for a human''s eyes. The other is for a physics engine checking contact many times per second.', 10, 1),
  ('mission-vec-simulation-02-o2-c1', 'solution', 'Visual geometry is detailed for rendering; collision geometry is simplified specifically because it has to be checked cheaply and often.', 20, 2),

  ('mission-vec-simulation-03-o1-c1', 'orientation', 'Ask which system computes motion, which one draws pictures, and which one connects everything to ROS 2.', 10, 1),
  ('mission-vec-simulation-03-o1-c1', 'solution', 'Physics engine: forces, collisions, contact checks. Rendering engine: what a camera sees. Plugin system: bridging sensor output onto topics.', 20, 2),
  ('mission-vec-simulation-03-o2-c1', 'orientation', 'ROS 2 only ever sees topics and messages -- ask what actually produces those from inside the simulator.', 10, 1),
  ('mission-vec-simulation-03-o2-c1', 'solution', 'Without a plugin publishing to a topic, the rest of the stack has no way to observe the simulator at all.', 20, 2),

  ('mission-vec-simulation-04-o1-c1', 'orientation', 'A robot model ends at the robot''s own outer surface -- ask what describes everything past that.', 10, 1),
  ('mission-vec-simulation-04-o1-c1', 'solution', 'A world file specifies the static environment around the robot -- ground, obstacles, lighting -- not the robot itself.', 20, 2),
  ('mission-vec-simulation-04-o2-c1', 'orientation', 'Compare what the real aisle actually contains against what the world file actually contains.', 10, 1),
  ('mission-vec-simulation-04-o2-c1', 'solution', 'e1 and e2 together: the real aisle has uneven flooring, shelving and dust, while the world file is still the generic template plane -- no real match at all.', 20, 2),

  ('mission-vec-simulation-05-o1-c1', 'orientation', 'A simulated sensor has no physical world to bounce a real signal off of.', 10, 1),
  ('mission-vec-simulation-05-o1-c1', 'solution', 'It casts virtual rays through known simulated geometry and computes where they stop -- entirely calculated, nothing physically measured.', 20, 2),
  ('mission-vec-simulation-05-o2-c1', 'orientation', 'Ask what perception code actually reads: the sensor''s physical existence, or its message on a topic.', 10, 1),
  ('mission-vec-simulation-05-o2-c1', 'solution', 'A well-built plugin matches the real sensor''s message type and topic interface, so downstream code cannot tell the two apart structurally.', 20, 2),

  ('mission-vec-simulation-06-o1-c1', 'orientation', 'Think about what makes a wheel spin freely versus grip the ground.', 10, 1),
  ('mission-vec-simulation-06-o1-c1', 'solution', 'Friction coefficient measures how much two surfaces resist sliding against each other.', 20, 2),
  ('mission-vec-simulation-06-o2-c1', 'orientation', 'Look for evidence about whether the number was ever changed, and whether it was ever compared against reality.', 10, 1),
  ('mission-vec-simulation-06-o2-c1', 'solution', 'e1 and e2 together: the value is still the unmodified template default, and it has never been compared to a real floor measurement.', 20, 2),

  ('mission-vec-simulation-07-o1-c1', 'orientation', 'Nothing physical is ever perfectly still or perfectly measured.', 10, 1),
  ('mission-vec-simulation-07-o1-c1', 'solution', 'Electrical noise, vibration and the sensor''s own imperfections introduce small random variation into every real reading.', 20, 2),
  ('mission-vec-simulation-07-o2-c1', 'orientation', 'Compare the noise model''s configured number against what the real sensor was actually measured to do.', 10, 1),
  ('mission-vec-simulation-07-o2-c1', 'solution', 'e1 and e2 together: the simulated model uses an unchecked default standard deviation, while the real sensor''s measured noise is five times larger, with dropout the model does not represent at all.', 20, 2),

  ('mission-vec-simulation-08-o1-c1', 'orientation', 'Ask how much simulated time passes for one second of real time.', 10, 1),
  ('mission-vec-simulation-08-o1-c1', 'solution', 'Real-time factor is the ratio of simulated time to real wall-clock time.', 20, 2),
  ('mission-vec-simulation-08-o2-c1', 'orientation', 'Timing-sensitive behavior was only ever validated against one specific relationship between the two clocks.', 10, 1),
  ('mission-vec-simulation-08-o2-c1', 'solution', 'A controller tuned only at a real-time factor of one has no guarantee its timing-dependent behavior holds at any other factor.', 20, 2),

  ('mission-vec-simulation-09-o1-c1', 'orientation', 'A scenario has to be describable precisely enough that someone else could run the exact same test.', 10, 1),
  ('mission-vec-simulation-09-o1-c1', 'solution', 'It is a specific, written-down set of starting conditions and events, deliberately built to be repeated identically.', 20, 2),
  ('mission-vec-simulation-09-o2-c1', 'orientation', 'Ask what "it worked" actually means if nobody could ever run that exact same test again.', 10, 1),
  ('mission-vec-simulation-09-o2-c1', 'solution', 'Repeatability proves the behavior holds reliably and lets the same test be re-run after every future change.', 20, 2),

  ('mission-vec-simulation-10-o1-c1', 'orientation', 'A simulator already knows every fact about its own scene -- ask what that fact becomes once rendered.', 10, 1),
  ('mission-vec-simulation-10-o1-c1', 'solution', 'The simulator knows the exact ground truth of the scene, so every generated image comes with a perfect label automatically.', 20, 2),
  ('mission-vec-simulation-10-o2-c1', 'orientation', 'Ask what happens to a model trained on one scene, over and over, with nothing ever varied.', 10, 1),
  ('mission-vec-simulation-10-o2-c1', 'solution', 'Domain randomization protects against a model memorizing one simulated scene instead of generalizing to real-world variety.', 20, 2),

  ('mission-vec-simulation-11-o1-c1', 'orientation', 'HIL puts something real back into a loop that would otherwise be entirely simulated.', 10, 1),
  ('mission-vec-simulation-11-o1-c1', 'solution', 'It wires one real component directly into an otherwise simulated loop so its actual behavior has to agree with everything around it.', 20, 2),
  ('mission-vec-simulation-11-o2-c1', 'orientation', 'A pure software simulation can only ever check its own assumptions against themselves.', 10, 1),
  ('mission-vec-simulation-11-o2-c1', 'solution', 'It catches the actual difference between assumed behavior in software and a real component''s true behavior, before full deployment.', 20, 2),

  ('mission-vec-simulation-12-o1-c1', 'orientation', 'Compare the world file''s number against what facilities actually measured on the real floor.', 10, 1),
  ('mission-vec-simulation-12-o1-c1', 'solution', 'e1 and e2 together: 1.0 in the world file, an unmodified default, versus roughly 0.35 measured on the real floor -- close to a third of the simulated value.', 20, 2),
  ('mission-vec-simulation-12-o2-c1', 'orientation', 'Compare the plugin''s configured noise number against what the real lidar was actually measured to produce.', 10, 1),
  ('mission-vec-simulation-12-o2-c1', 'solution', 'e1 and e2 together: 0.01 meters in the plugin config, an unchecked default, versus roughly 0.05 meters measured on the real sensor, plus dropout noise the model never represented.', 20, 2),
  ('mission-vec-simulation-12-o3-c1', 'orientation', 'Ask what validation step specifically forces a real component to answer for itself instead of trusting a simulated number.', 10, 1),
  ('mission-vec-simulation-12-o3-c1', 'solution', 'Hardware-in-the-loop testing, putting the real lidar and real wheel traction into the loop, is exactly what would have surfaced both gaps first.', 20, 2),
  ('mission-vec-simulation-12-o4-c1', 'orientation', 'Combine the physics gap, the noise-model gap, and the validation step that would have caught both into one diagnosis.', 15, 1),
  ('mission-vec-simulation-12-o4-c1', 'solution', 'The friction coefficient and the lidar noise model were both left at unmodified simulator defaults instead of real measured values, and hardware-in-the-loop testing is exactly the validation step that would have caught both before the scenario ever reached the real floor.', 25, 2);
